// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    Recorder rec;

    function setUp() public { 
        c = new airDrop();
        rec = new Recorder();
    }

    // fuzz parameters: sender (from), v (amount), decimals, single recipient address chosen from fuzzer
    function testFuzz_property(address from, uint256 v, uint256 decimals, address tos) public {
        // keep tos as a distinct non-zero address and decimals in a reasonable range to avoid overflow in multiplication
        vm.assume(tos != address(0));
        vm.assume(from != address(0));
        decimals = bound(decimals, 0, 36); // avoid overflow for 10**decimals in uint256

        // build a single-element array to ensure exactly one external call is made and recorded
        address[] memory tosArr = new address[](1);
        tosArr[0] = address(rec);

        // call transfer via prank as any caller (c doesn't restrict msg.sender), but we want from param arbitrary
        bool ok;
        try c.transfer(from, address(rec), tosArr, v, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The Recorder stored the last call's decoded amount and number of calls
        // For the reference contract, when ok==true (call succeeded) the recorded value must equal v * 10**decimals
        // For some inputs the mutant will cause a mismatch because it uses v + 10**decimals instead.

        // We assert the universal property: if the external call succeeded, the recorder's recordedValue == v * 10**decimals
        // (This will hold for the reference for all inputs; the mutant will fail for some inputs and the fuzzer will find them.)
        if (ok) {
            uint256 recorded = rec.recordedValue();
            uint256 expected = v * (10 ** decimals);
            assertTrue(recorded == expected);
        } else {
            // If the call reverted, the reference also must revert only if the callee reverts for that value;
            // We do not assert additional constraints when the call failed. Still, the above branch suffices to distinguish mutants.
            assertTrue(!ok || ok == false);
        }
    }
}

// Recorder that implements the exact signature transfer expects to call via selector
contract Recorder {
    uint256 public recordedValue;
    uint256 public callCount;
    address public lastFrom;
    address public lastTo;

    // match function selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        callCount += 1;
        recordedValue = value;
        lastFrom = from;
        lastTo = to;
        return true;
    }
}
